# =============================================================================
# Required Variables
# =============================================================================

variable "name" {
  description = "Name of the LXC container"
  type        = string
}

variable "container_id" {
  description = "Proxmox container ID"
  type        = number
}

variable "ip_address" {
  description = "Static IP address in CIDR notation (e.g., 192.168.1.100/24)"
  type        = string
}

variable "deploy_dir" {
  description = "Local directory containing deployment files (must include docker-compose.yml)"
  type        = string
}

variable "ssh_private_key_path" {
  description = "Path to SSH private key for container access"
  type        = string
}

# =============================================================================
# Container Configuration
# =============================================================================

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "pve"
}

variable "cores" {
  description = "CPU cores"
  type        = number
  default     = 2
}

variable "memory" {
  description = "Memory in MB"
  type        = number
  default     = 2048
}

variable "swap" {
  description = "Swap in MB"
  type        = number
  default     = 1024
}

variable "rootfs_size" {
  description = "Root filesystem size in GB"
  type        = number
  default     = 8
}

variable "rootfs_storage" {
  description = "Storage pool for root filesystem"
  type        = string
  default     = "nvme-containers"
}

variable "unprivileged" {
  description = "Run as unprivileged container (false = privileged, better Docker compatibility)"
  type        = bool
  default     = false
}

variable "template" {
  description = "LXC template to use (should be Docker-ready)"
  type        = string
  default     = "local:vztmpl/debian-13-docker_1.0_amd64.tar.zst"
}

# =============================================================================
# Network Configuration
# =============================================================================

variable "gateway" {
  description = "Default gateway IP"
  type        = string
  default     = "192.168.1.1"
}

# =============================================================================
# SSH Configuration
# =============================================================================

variable "ssh_public_key" {
  description = "SSH public key for root user"
  type        = string
  default     = ""
}

variable "proxmox_ssh_host" {
  description = "Proxmox host for SSH (for privileged container feature config)"
  type        = string
  default     = "homelab"
}

# =============================================================================
# File Sync Configuration
# =============================================================================

variable "target_path" {
  description = "Target path on container for config files"
  type        = string
  default     = "/config"
}

variable "config_owner" {
  description = "Owner for synced config files"
  type        = string
  default     = ""
}

variable "config_group" {
  description = "Group for synced config files"
  type        = string
  default     = ""
}

variable "file_permissions" {
  description = "Map of file paths to chmod permissions"
  type        = map(string)
  default     = {}
}

variable "delete_extra_files" {
  description = "Delete files on target that don't exist in source"
  type        = bool
  default     = true
}

variable "post_sync_commands" {
  description = "Additional commands to run after file sync"
  type        = list(string)
  default     = []
}

variable "exclude_patterns" {
  description = "List of glob patterns to exclude from file sync (e.g., ['migrated-dynamic/**'])"
  type        = list(string)
  default     = []
}

# =============================================================================
# Docker Compose Configuration
# =============================================================================

variable "docker_compose_up" {
  description = "Run docker compose up after deployment"
  type        = bool
  default     = true
}

variable "docker_compose_validate" {
  description = "Validate docker compose file"
  type        = bool
  default     = true
}

# =============================================================================
# Proxmox Notes Configuration
# =============================================================================

variable "enable_proxmox_notes" {
  description = "Enable automatic Proxmox notes generation"
  type        = bool
  default     = true
}

variable "service_name" {
  description = "Service name for Proxmox notes (defaults to container name)"
  type        = string
  default     = ""
}

variable "service_description" {
  description = "Service description for Proxmox notes"
  type        = string
  default     = ""
}

variable "service_urls" {
  description = "Service URLs for Proxmox notes"
  type        = map(string)
  default     = {}
}

variable "services" {
  description = "List of services running in the container"
  type = list(object({
    name = string
    port = number
    info = string
  }))
  default = []
}

variable "custom_notes" {
  description = "Custom notes to append to Proxmox notes"
  type        = string
  default     = ""
}

# =============================================================================
# Storage Configuration
# =============================================================================

variable "mount_points" {
  description = "List of mount points for the container"
  type = list(object({
    slot   = number
    path   = string
    volume = string
  }))
  default = []
}

# =============================================================================
# Miscellaneous
# =============================================================================

variable "tags" {
  description = "Additional tags for the container"
  type        = list(string)
  default     = []
}

