# =============================================================================
# Provider Versions and Configuration
# =============================================================================
# This file is symlinked into each app directory.
# Providers use secrets from 1Password via local.op.* (defined in onepassword.tf)
# =============================================================================

terraform {
  required_version = ">= 1.7.0"

  required_providers {
    proxmox = {
      source  = "bpg/proxmox"
      version = "~> 0.69"
    }
    onepassword = {
      source  = "1password/onepassword"
      version = "~> 2.1"
    }
    cloudflare = {
      source  = "cloudflare/cloudflare"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.12"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    # Custom providers for file sync and docker compose management
    filesync = {
      source  = "darshan-rambhia/filesync"
      version = "~> 0.3"
    }
    remotedockercompose = {
      source  = "darshan-rambhia/remote-docker-compose-file"
      version = "~> 0.3"
    }
  }

  # Encrypted local state - safe to commit to git
  # Note: state_encryption_passphrase must be provided via TF_VAR
  # because encryption runs before providers are initialized
  encryption {
    key_provider "pbkdf2" "main" {
      passphrase = var.state_encryption_passphrase
    }

    method "aes_gcm" "default" {
      keys = key_provider.pbkdf2.main
    }

    state {
      method   = method.aes_gcm.default
      enforced = true
    }

    plan {
      method   = method.aes_gcm.default
      enforced = true
    }
  }
}

# -----------------------------------------------------------------------------
# 1Password Provider
# -----------------------------------------------------------------------------
# Authentication via CLI with biometric unlock
# Requires: op CLI v2.23.0+, signed in account

provider "onepassword" {
  # Uses biometric authentication via 1Password CLI
  # Set OP_ACCOUNT env var or account field to your 1Password account URL
  account = "rambhia.1password.com"
}

# -----------------------------------------------------------------------------
# Proxmox Provider
# -----------------------------------------------------------------------------
# API token fetched from 1Password

provider "proxmox" {
  endpoint  = var.proxmox_endpoint
  api_token = local.op.proxmox_api_token
  insecure  = true

  ssh {
    agent       = true
    username    = "root"
    private_key = file(var.ssh_private_key_path)
  }
}

# -----------------------------------------------------------------------------
# Cloudflare Provider
# -----------------------------------------------------------------------------
# API token fetched from 1Password

provider "cloudflare" {
  api_token = local.op.cloudflare_api_token
}

# -----------------------------------------------------------------------------
# Filesync Provider
# -----------------------------------------------------------------------------
# SSH-based file synchronization to remote hosts

provider "filesync" {
  ssh_user                 = "root"
  ssh_key_path             = pathexpand(var.ssh_private_key_path)
  known_hosts_file         = pathexpand("~/.ssh/known_hosts")
  strict_host_key_checking = "accept-new"
}

# -----------------------------------------------------------------------------
# Remote Docker Compose Provider
# -----------------------------------------------------------------------------
# Manage Docker Compose stacks on remote hosts via SSH

provider "remotedockercompose" {
  ssh_user                 = "root"
  ssh_key_path             = pathexpand(var.ssh_private_key_path)
  known_hosts_file         = pathexpand("~/.ssh/known_hosts")
  strict_host_key_checking = "accept-new"
}

# =============================================================================
# Traefik Route Module
# =============================================================================
# Generates and syncs Traefik dynamic configuration for an app.
# Each app can self-register its routes without modifying Traefik configs.
#
# Features:
# - Auto-generates YAML config from variables
# - Syncs to Traefik LXC via file-sync module
# - Supports internal (websecure) and public (web) routes
# - Health checks, middlewares, custom options
#
# Usage:
#   module "n8n_route" {
#     source = "../../modules/traefik-route"
#
#     app_name    = "n8n"
#     backend_url = "http://192.168.1.213:5678"
#
#     internal_domain = "n8n.homelab.rambtech.dev"
#     public_domain   = ""  # Optional
#
#     traefik_host         = "192.168.1.162"
#     ssh_private_key_path = var.ssh_private_key_path
#   }
# =============================================================================

terraform {
  required_providers {
    local = {
      source = "hashicorp/local"
    }
    filesync = {
      source = "darshan-rambhia/filesync"
    }
    null = {
      source = "hashicorp/null"
    }
  }
}

